{"command": "cat > /prediction.json << 'ENDOFJSON'
{
    "vllm/model_executor/layers/quantization/awq_triton.py": {
        "awq_dequantize_kernel": "@triton.jit\ndef awq_dequantize_kernel(\n        qweight_ptr,  # quantized matrix [num_rows, num_cols], int32\n        scales_ptr,  # scales [num_rows // group_size, num_cols * 8], float16\n        zeros_ptr,  # zeros [num_rows // group_size, num_cols], int32\n        group_size,  # group size for quantization\n        result_ptr,  # Output matrix [num_rows, num_cols * 8], float16\n        num_cols,  # input num cols in qweight\n        num_rows,  # input num rows in qweight\n        BLOCK_SIZE_X: tl.constexpr,\n        BLOCK_SIZE_Y: tl.constexpr):\n    \"\"\"\n    AWQ dequantization kernel.\n    \n    Each int32 in qweight contains 8 packed 4-bit values.\n    AWQ reverse order [0, 4, 1, 5, 2, 6, 3, 7] is applied after unpacking.\n    \"\"\"\n    pid_x = tl.program_id(axis=0)\n    pid_y = tl.program_id(axis=1)\n    \n    row_start = pid_y * BLOCK_SIZE_Y\n    col_start = pid_x * BLOCK_SIZE_X\n    \n    row_offs = row_start + tl.arange(0, BLOCK_SIZE_Y)\n    col_offs = col_start + tl.arange(0, BLOCK_SIZE_X)\n    \n    row_mask = row_offs < num_rows\n    col_mask = col_offs < num_cols\n    \n    # Load qweight and zeros\n    qweight_offs = row_offs[:, None] * num_cols + col_offs[None, :]\n    qweight = tl.load(qweight_ptr + qweight_offs, \n                      mask=row_mask[:, None] & col_mask[None, :], \n                      other=0)\n    \n    zeros_offs = (row_offs[:, None] // group_size) * num_cols + col_offs[None, :]\n    zeros = tl.load(zeros_ptr + zeros_offs,\n                    mask=row_mask[:, None] & col_mask[None, :],\n                    other=0)\n    \n    # AWQ reverse order: output[i] comes from unpacked[AWQ_REVERSE_ORDER[i]]\n    AWQ_REVERSE_ORDER = [0, 4, 1, 5, 2, 6, 3, 7]\n    \n    # Process each of the 8 4-bit values\n    for i in range(8):\n        reverse_i = AWQ_REVERSE_ORDER[i]\n        shift = reverse_i * 4\n        \n        # Extract 4-bit values\n        qweight_i = (qweight >> shift) & 0xF\n        zeros_i = (zeros >> shift) & 0xF\n        \n        # Output column index\n        out_col = col_offs[None, :] * 8 + i\n        \n        # Load scales\n        scales_offs = (row_offs[:, None] // group_size) * (num_cols * 8) + out_col\n        scales_i = tl.load(scales_ptr + scales_offs,\n                          mask=row_mask[:, None] & (out_col < num_cols * 8),\n                          other=0.0)\n        \n        # Dequantize\n        result_i = (qweight_i.to(tl.float16) - zeros_i.to(tl.float16)) * scales_i\n        \n        # Store result\n        result_offs = row_offs[:, None] * (num_cols * 8) + out_col\n        tl.store(result_ptr + result_offs, result_i,\n                 mask=row_mask[:, None] & (out_col < num_cols * 8))",
        "awq_gemm_kernel": "@triton.jit\ndef awq_gemm_kernel(a_ptr, b_ptr, c_ptr, zeros_ptr, scales_ptr, M, N, K,\n                    group_size, BLOCK_SIZE_M: tl.constexpr,\n                    BLOCK_SIZE_N: tl.constexpr, BLOCK_SIZE_K: tl.constexpr,\n                    SPLIT_K: tl.constexpr):\n    \"\"\"\n    AWQ GEMM kernel with on-the-fly dequantization.\n    \n    a: [M, K], float32 - input activations\n    b: [K, N // 8], int32 - quantized weights (4-bit packed)\n    c: [M, N], float32 - output\n    zeros: [K // G, N // 8], int32 - packed 4-bit zeros\n    scales: [K // G, N], float32 - per-group scales\n    \"\"\"\n    pid = tl.program_id(axis=0)\n    pid_sk = tl.program_id(axis=1)\n    \n    num_blocks_m = tl.cdiv(M, BLOCK_SIZE_M)\n    pid_m = pid // num_blocks_m\n    pid_n = pid % num_blocks_m\n    \n    m_start = pid_m * BLOCK_SIZE_M\n    n_start = pid_n * BLOCK_SIZE_N\n    k_start = pid_sk * BLOCK_SIZE_K\n    \n    m_offs = m_start + tl.arange(0, BLOCK_SIZE_M)\n    n_offs = n_start + tl.arange(0, BLOCK_SIZE_N)\n    k_offs = k_start + tl.arange(0, BLOCK_SIZE_K)\n    \n    m_mask = m_offs < M\n    n_mask = n_offs < N\n    k_mask = k_offs < K\n    \n    # Load input activations\n    a_offs = m_offs[:, None] * K + k_offs[None, :]\n    a = tl.load(a_ptr + a_offs, mask=m_mask[:, None] & k_mask[None, :], other=0.0)\n    \n    accumulator = tl.zeros((BLOCK_SIZE_M, BLOCK_SIZE_N), dtype=tl.float32)\n    \n    AWQ_REVERSE_ORDER = [0, 4, 1, 5, 2, 6, 3, 7]\n    num_k_blocks = tl.cdiv(K, BLOCK_SIZE_K * SPLIT_K)\n    \n    for kb in range(num_k_blocks):\n        k_base = k_start + kb * BLOCK_SIZE_K * SPLIT_K\n        k_curr_offs = k_base + tl.arange(0, BLOCK_SIZE_K)\n        k_curr_mask = k_curr_offs < K\n        \n        for i in range(8):\n            bit_n_mask = (n_offs % 8 == i) & n_mask\n            \n            if tl.sum(bit_n_mask.to(tl.int32)) > 0:\n                b_col = n_offs // 8\n                \n                b_offs = k_curr_offs[:, None] * (N // 8) + b_col[None, :]\n                b_mask_2d = k_curr_mask[:, None] & (b_col[None, :] < N // 8)\n                b = tl.load(b_ptr + b_offs, mask=b_mask_2d, other=0)\n                \n                zeros_offs = (k_curr_offs[:, None] // group_size) * (N // 8) + b_col[None, :]\n                zeros_mask_2d = k_curr_mask[:, None] & (b_col[None, :] < N // 8)\n                zeros = tl.load(zeros_ptr + zeros_offs, mask=zeros_mask_2d, other=0)\n                \n                scales_offs = (k_curr_offs[:, None] // group_size) * N + n_offs[None, :]\n                scales_mask_2d = k_curr_mask[:, None] & n_mask[None, :]\n                scales = tl.load(scales_ptr + scales_offs, mask=scales_mask_2d, other=0.0)\n                \n                reverse_i = AWQ_REVERSE_ORDER[i]\n                shift = reverse_i * 4\n                b_i = (b >> shift) & 0xF\n                zeros_i = (zeros >> shift) & 0xF\n                \n                b_dequant = (b_i.to(tl.float32) - zeros_i.to(tl.float32)) * scales\n                \n                b_masked = tl.where(bit_n_mask[None, :], b_dequant, 0.0)\n                accumulator += tl.dot(a, b_masked)\n    \n    c_offs = m_offs[:, None] * N + n_offs[None, :]\n    c_mask = m_mask[:, None] & n_mask[None, :]\n    \n    if SPLIT_K == 1:\n        tl.store(c_ptr + c_offs, accumulator, mask=c_mask)\n    else:\n        tl.atomic_add(c_ptr + c_offs, accumulator, mask=c_mask)",
        "awq_dequantize_triton": "def awq_dequantize_triton(qweight: torch.Tensor,\n                          scales: torch.Tensor,\n                          zeros: torch.Tensor,\n                          block_size_x: int = 32,\n                          block_size_y: int = 32) -> torch.Tensor:\n    \"\"\"\n    AWQ dequantization using Triton kernel.\n    \n    Args:\n        qweight: [num_rows, num_cols], int32 - quantized weights\n        scales: [num_rows // group_size, num_cols * 8], float16 - per-group scales\n        zeros: [num_rows // group_size, num_cols], int32 - packed 4-bit zeros\n        block_size_x: block size in x dimension\n        block_size_y: block size in y dimension\n    \n    Returns:\n        result: [num_rows, num_cols * 8], float16 - dequantized weights\n    \"\"\"\n    num_rows, num_cols = qweight.shape\n    group_size = num_rows // scales.shape[0]\n    \n    result = torch.empty((num_rows, num_cols * 8), \n                         dtype=torch.float16, \n                         device=qweight.device)\n    \n    grid_x = triton.cdiv(num_cols, block_size_x)\n    grid_y = triton.cdiv(num_rows, block_size_y)\n    \n    awq_dequantize_kernel[grid_x, grid_y](\n        qweight,\n        scales,\n        zeros,\n        group_size,\n        result,\n        num_cols,\n        num_rows,\n        BLOCK_SIZE_X=block_size_x,\n        BLOCK_SIZE_Y=block_size_y,\n    )\n    \n    return result",
        "awq_gemm_triton": "def awq_gemm_triton(a: torch.Tensor,\n                    b: torch.Tensor,\n                    scales: torch.Tensor,\n                    zeros: torch.Tensor,\n                    split_k_iters: int = 1) -> torch.Tensor:\n    \"\"\"\n    AWQ GEMM using Triton kernel.\n    \n    Args:\n        a: [M, K], float32 - input activations\n        b: [K, N // 8], int32 - quantized weights\n        scales: [K // G, N], float32 - per-group scales\n        zeros: [K // G, N // 8], int32 - packed 4-bit zeros\n        split_k_iters: number of splits along K dimension\n    \n    Returns:\n        c: [M, N], float32 - output\n    \"\"\"\n    M, K = a.shape\n    N = scales.shape[1]\n    group_size = K // scales.shape[0]\n    \n    BLOCK_SIZE_M = 64\n    BLOCK_SIZE_N = 64\n    BLOCK_SIZE_K = 32\n    \n    c = torch.zeros((M, N), dtype=torch.float32, device=a.device)\n    \n    grid_m = triton.cdiv(M, BLOCK_SIZE_M)\n    grid_n = triton.cdiv(N, BLOCK_SIZE_N)\n    grid = (grid_m * grid_n, split_k_iters)\n    \n    awq_gemm_kernel[grid](\n        a,\n        b,\n        c,\n        zeros,\n        scales,\n        M, N, K,\n        group_size,\n        BLOCK_SIZE_M=BLOCK_SIZE_M,\n        BLOCK_SIZE_N=BLOCK_SIZE_N,\n        BLOCK_SIZE_K=BLOCK_SIZE_K,\n        SPLIT_K=split_k_iters,\n    )\n    \n    return c"
    }
}
ENDOFJSON
